<script setup lang="ts">import{apiErrorMessage}from'~/utils/api-error';useHead({title:'Nouveau mot de passe'});const route=useRoute();const token=computed(()=>typeof route.query.token==='string'?route.query.token:'');const password=ref('');const confirmation=ref('');const pending=ref(false);const done=ref(false);const errorMessage=ref('');async function submit(){if(password.value!==confirmation.value){errorMessage.value='Les deux mots de passe ne correspondent pas.';return}pending.value=true;errorMessage.value='';try{await $fetch('/api/auth/password/reset',{method:'POST',body:{token:token.value,newPassword:password.value}});done.value=true}catch(error){errorMessage.value=apiErrorMessage(error,'Le lien est invalide ou expiré.')}finally{pending.value=false}}</script>
<template><section class="section"><div class="container auth-narrow"><div v-if="!token" class="alert alert-error">Lien de réinitialisation incomplet.</div><div v-else-if="done" class="card card-pad"><h1>Mot de passe modifié</h1><p>Vos anciennes sessions ont été révoquées.</p><NuxtLink to="/login" class="btn btn-primary">Se connecter</NuxtLink></div><form v-else class="card card-pad" @submit.prevent="submit"><h1>Choisir un nouveau mot de passe</h1><p class="muted">Utilisez au minimum 12 caractères et évitez un mot de passe déjà utilisé ailleurs.</p><div v-if="errorMessage" class="alert alert-error" role="alert">{{errorMessage}}</div><div class="field"><label for="new-password">Nouveau mot de passe</label><input id="new-password" v-model="password" class="input" type="password" minlength="12" autocomplete="new-password" required></div><div class="field"><label for="confirm-password">Confirmation</label><input id="confirm-password" v-model="confirmation" class="input" type="password" minlength="12" autocomplete="new-password" required></div><button class="btn btn-primary" type="submit" :disabled="pending">{{pending?'Validation…':'Enregistrer'}}</button></form></div></section></template>
<style scoped>.auth-narrow{max-width:560px}.card{display:flex;flex-direction:column;gap:16px}.card h1,.card p{margin:0}</style>
